//! The frozen v2 store fixture (P3-0c).
//!
//! Profile v3 will refuse v2 roots, so once it lands a *real* v2 store can no longer be produced. This fixture
//! is that store, generated by the v2 writer (see `README.md` for the commit and the exact values) and frozen
//! read-only. The tests here answer three questions and nothing else:
//!
//! 1. **is it the same fixture?** — every file's `(path, length, BLAKE3)` must match the manifest in the README;
//! 2. **does it still read?** — the recorded root opens through the v2 reader and its content object carries the
//!    recorded hash;
//! 3. **was it left alone?** — `(path, length, mtime)` is identical before and after, so a test that writes here
//!    fails instead of quietly rewriting the evidence.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

/// `crates/fs-snapshot/tests/fixtures/snapshot-v2-store`.
fn fixture_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("snapshot-v2-store")
}

fn store_dir() -> PathBuf {
    fixture_root().join("store")
}

/// `(relative path, length)` for every file under `dir`, sorted.
fn inventory(dir: &Path) -> BTreeMap<String, (u64, std::time::SystemTime)> {
    let mut out = BTreeMap::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(current) = stack.pop() {
        for entry in std::fs::read_dir(&current)
            .expect("read the fixture")
            .flatten()
        {
            let path = entry.path();
            let meta = entry.metadata().expect("metadata");
            if meta.is_dir() {
                stack.push(path);
            } else {
                let relative = path
                    .strip_prefix(dir)
                    .expect("inside the fixture")
                    .to_string_lossy()
                    .replace('\\', "/");
                if is_volatile(&relative) {
                    continue;
                }
                out.insert(relative, (meta.len(), meta.modified().expect("mtime")));
            }
        }
    }
    out
}

/// SQLite's `-shm`/`-wal` companions are created by *opening* a database and carry no fixture content.
///
/// They are excluded from both the manifest and the read-only comparison for the same reason the store's own
/// GC excludes them (ADR-008 §6.1): a file whose length depends on who opened the database is not evidence.
fn is_volatile(relative: &str) -> bool {
    relative.ends_with("-shm") || relative.ends_with("-wal")
}

/// Files that describe the fixture rather than belong to it: the README (which publishes the manifest) and the
/// `.gitignore` that keeps SQLite's companions out of the repository.
fn is_metadata(relative: &str) -> bool {
    relative == "README.md" || relative == ".gitignore"
}

fn blake3_of(path: &Path) -> String {
    let bytes = std::fs::read(path).expect("read a fixture file");
    blake3::hash(&bytes).to_hex().to_string()
}

/// The manifest the README publishes, parsed from its fenced `manifest` block.
///
/// The README is the **single source**: the fixture and one document cannot drift apart without this test
/// noticing, which is the point of a frozen fixture.
fn readme_manifest() -> BTreeMap<String, (u64, String)> {
    let readme = std::fs::read_to_string(fixture_root().join("README.md")).expect("fixture README");
    let mut out = BTreeMap::new();
    let mut inside = false;
    for line in readme.lines() {
        if line.trim() == "```manifest" {
            inside = true;
            continue;
        }
        if inside {
            if line.trim() == "```" {
                break;
            }
            if line.trim().is_empty() {
                continue;
            }
            let mut parts = line.split_whitespace();
            let path = parts.next().expect("a path");
            let length: u64 = parts.next().expect("a length").parse().expect("a number");
            let hash = parts.next().expect("a hash").to_owned();
            out.insert(path.to_owned(), (length, hash));
        }
    }
    assert!(!out.is_empty(), "the README must publish a manifest block");
    out
}

#[test]
fn every_fixture_file_matches_the_readme_manifest() {
    let manifest = readme_manifest();
    let root = fixture_root();
    let mut actual = BTreeMap::new();
    let mut stack = vec![root.clone()];
    while let Some(current) = stack.pop() {
        for entry in std::fs::read_dir(&current)
            .expect("read the fixture")
            .flatten()
        {
            let path = entry.path();
            if entry.metadata().expect("metadata").is_dir() {
                stack.push(path);
            } else {
                let relative = path
                    .strip_prefix(&root)
                    .expect("inside the fixture")
                    .to_string_lossy()
                    .replace('\\', "/");
                if is_metadata(&relative) || is_volatile(&relative) {
                    continue;
                }
                actual.insert(relative, path);
            }
        }
    }

    let mut problems = Vec::new();
    for (relative, (length, hash)) in &manifest {
        match actual.get(relative) {
            None => problems.push(format!("missing file {relative}")),
            Some(path) => {
                let meta = std::fs::metadata(path).expect("metadata");
                if meta.len() != *length {
                    problems.push(format!(
                        "{relative}: length {} != manifest {length}",
                        meta.len()
                    ));
                }
                let computed = blake3_of(path);
                if computed != *hash {
                    problems.push(format!("{relative}: blake3 {computed} != manifest {hash}"));
                }
            }
        }
    }
    for relative in actual.keys() {
        if !manifest.contains_key(relative) {
            problems.push(format!("{relative} is not in the manifest"));
        }
    }
    assert!(
        problems.is_empty(),
        "the fixture does not match its manifest (do NOT regenerate it to make this pass):\n{}",
        problems.join("\n")
    );
    assert_eq!(
        manifest.len(),
        actual.len(),
        "the manifest must list every file exactly once"
    );
}

/// The recorded root still opens with the **v2** reader, and the content object carries the recorded hash.
///
/// This is what makes the fixture usable as P3-2's "refuse an old root" subject: an object graph that a v2
/// reader can walk end to end.
#[test]
fn the_recorded_root_still_reads_with_the_v2_profile() {
    let readme = std::fs::read_to_string(fixture_root().join("README.md")).expect("README");
    let root_id = readme
        .lines()
        .find_map(|line| line.strip_prefix("- root: ").map(str::trim))
        .expect("the README records the root id");
    let root: cas_core::ObjectId = root_id.parse().expect("a root id");
    let content_hash = readme
        .lines()
        .find_map(|line| line.strip_prefix("- content blake3: ").map(str::trim))
        .expect("the README records the content hash");
    let content_len: u64 = readme
        .lines()
        .find_map(|line| line.strip_prefix("- content length: ").map(str::trim))
        .expect("the README records the content length")
        .parse()
        .expect("a number");

    let store = cas_store::Store::open(store_dir(), cas_store::OpenMode::ReadOnly)
        .expect("open the fixture");
    // `open_any` rather than a hard-coded profile: the root carries its own profile id, and the README records
    // which one this fixture was written under — hard-coding V1 here would be a second, silent claim.
    let reader =
        fs_snapshot::SnapshotReader::open_any(&store, root).expect("the recorded root reads");

    // Walk the graph the way the collector does and find the object with the recorded length and hash.
    let mut best: Option<(cas_core::ObjectId, String, u64)> = None;
    let mut visited = std::collections::BTreeSet::new();
    let mut queue = vec![root];
    while let Some(oid) = queue.pop() {
        if !visited.insert(oid) {
            continue;
        }
        let bytes = store.get(oid).expect("every reachable object is readable");
        let object = cas_core::Object::decode(&bytes).expect("a well-formed object");
        let value_len = u64::try_from(object.value().len()).expect("fits");
        if value_len == content_len && best.is_none() {
            let hash = blake3::hash(object.value()).to_hex().to_string();
            best = Some((oid, hash, value_len));
        }
        queue.extend(reader.references(oid).expect("references"));
    }
    let (oid, hash, len) = best.expect("the fixture must contain the recorded content object");
    assert_eq!(len, content_len, "cell content object {oid}: length");
    assert_eq!(
        hash, content_hash,
        "cell content object {oid}: the bytes are the ones the fixture was generated from"
    );
}

/// Reading the fixture must not change it: `(path, length, mtime)` identical before and after.
#[test]
fn reading_the_fixture_does_not_touch_it() {
    let before = inventory(&store_dir());
    let _ = the_recorded_root_still_reads_with_the_v2_profile_body();
    let after = inventory(&store_dir());
    assert_eq!(
        before.len(),
        after.len(),
        "the number of fixture files changed"
    );
    for (path, (length, modified)) in &before {
        let (after_length, after_modified) = after.get(path).expect("the file still exists");
        assert_eq!(length, after_length, "cell path={path}: length changed");
        assert_eq!(
            modified, after_modified,
            "cell path={path}: mtime changed — the fixture is read-only"
        );
    }
}

/// The body of the read test, without its assertions about the manifest (so the read-only test can reuse it
/// without depending on the README's wording).
fn the_recorded_root_still_reads_with_the_v2_profile_body() -> Option<()> {
    let store = cas_store::Store::open(store_dir(), cas_store::OpenMode::ReadOnly).ok()?;
    let readme = std::fs::read_to_string(fixture_root().join("README.md")).ok()?;
    let root_id = readme
        .lines()
        .find_map(|line| line.strip_prefix("- root: ").map(str::trim))?;
    let root: cas_core::ObjectId = root_id.parse().ok()?;
    let reader = fs_snapshot::SnapshotReader::open_any(&store, root).ok()?;
    // Touch the graph so any write-on-read behaviour would show up in the mtime comparison.
    let _ = reader.references(root).ok()?;
    Some(())
}

/// Prints the manifest to paste into the README. **Not** a way to fix a failing manifest: the card's whole point
/// is that this fixture is not regenerated.
#[test]
#[ignore = "prints the manifest for the README; not a repair tool"]
fn print_manifest() {
    let root = fixture_root();
    let mut stack = vec![root.clone()];
    let mut rows = Vec::new();
    while let Some(current) = stack.pop() {
        for entry in std::fs::read_dir(&current)
            .expect("read the fixture")
            .flatten()
        {
            let path = entry.path();
            if entry.metadata().expect("metadata").is_dir() {
                stack.push(path);
            } else {
                let relative = path
                    .strip_prefix(&root)
                    .expect("inside")
                    .to_string_lossy()
                    .replace('\\', "/");
                if is_metadata(&relative) || is_volatile(&relative) {
                    continue;
                }
                let length = std::fs::metadata(&path).expect("metadata").len();
                rows.push((relative, length, blake3_of(&path)));
            }
        }
    }
    rows.sort();
    println!("```manifest");
    for (relative, length, hash) in rows {
        println!("{relative} {length} {hash}");
    }
    println!("```");
}
